"573 :   void renameProperties() {
574 :     int propsRenamed = 0, propsSkipped = 0, instancesRenamed = 0,
575 :         instancesSkipped = 0, singleTypeProps = 0;
576 : 
577 :     Set<String> reported = Sets.newHashSet();
578 :     for (Property prop : properties.values()) {
579 :       if (prop.shouldRename()) {
580 :         Map<T, String> propNames = buildPropNames(prop.getTypes(), prop.name);
581 : 
582 :         ++propsRenamed;
583 :         prop.expandTypesToSkip();
584 :         for (Node node : prop.renameNodes) {
585 :           T rootType = prop.rootTypes.get(node);
586 :           if (prop.shouldRename(rootType)) {
587 :             String newName = propNames.get(rootType);
588 :             node.setString(newName);
589 :             compiler.reportCodeChange();
590 :             ++instancesRenamed;
591 :           } else {
592 :             ++instancesSkipped;
593 : 
594 :             CheckLevel checkLevelForProp = propertiesToErrorFor.get(prop.name);
595 :             if (checkLevelForProp != null &&
596 :                 checkLevelForProp != CheckLevel.OFF &&
597 :                 !reported.contains(prop.name)) {
598 :               reported.add(prop.name);
599 :               compiler.report(JSError.make(
600 :                   NodeUtil.getSourceName(node), node,
601 :                   checkLevelForProp,
602 :                   Warnings.INVALIDATION_ON_TYPE, prop.name,
603 :                   rootType.toString(), ""));
604 :             }
605 :           }
606 :         }
607 :       } else {
608 :         if (prop.skipRenaming) {
609 :           ++propsSkipped;
610 :         } else {
611 :           ++singleTypeProps;
612 :         }
613 :       }
614 :     }
615 :     logger.fine("Renamed " + instancesRenamed + " instances of "
616 :                 + propsRenamed + " properties.");
617 :     logger.fine("Skipped renaming " + instancesSkipped + " invalidated "
618 :                 + "properties, " + propsSkipped + " instances of properties "
619 :                 + "that were skipped for specific types and " + singleTypeProps
620 :                 + " properties that were referenced from only one type.");
621 :   }"

"854 :     @Override public ObjectType getTypeWithProperty(String field, JSType type) {
855 :       if (type == null) {
856 :         return null;
857 :       }
858 : 
859 :       if (type.isEnumElementType()) {
860 :         return getTypeWithProperty(
861 :             field, type.toMaybeEnumElementType().getPrimitiveType());
862 :       }
863 : 
864 :       if (!(type instanceof ObjectType)) {
865 :         if (type.autoboxesTo() != null) {
866 :           type = type.autoboxesTo();
867 :         } else {
868 :           return null;
869 :         }
870 :       }
871 : 
872 :       // Ignore the prototype itself at all times.
873 :       if ("prototype".equals(field)) {
874 :         return null;
875 :       }
876 : 
877 :       // We look up the prototype chain to find the highest place (if any) that
878 :       // this appears.  This will make references to overridden properties look
879 :       // like references to the initial property, so they are renamed alike.
880 :       ObjectType foundType = null;
881 :       ObjectType objType = ObjectType.cast(type);
882 :       if (objType != null && objType.getConstructor() != null
883 :           && objType.getConstructor().isInterface()) {
884 :         ObjectType topInterface = FunctionType.getTopDefiningInterface(
885 :             objType, field);
886 :         if (topInterface != null && topInterface.getConstructor() != null) {
887 :           foundType = topInterface.getConstructor().getPrototype();
888 :         }
889 :       } else {
890 :         while (objType != null && objType.getImplicitPrototype() != objType) {
891 :           if (objType.hasOwnProperty(field)) {
892 :             foundType = objType;
893 :           }
894 :           objType = objType.getImplicitPrototype();
895 :         }
896 :       }
897 : 
898 :       // If the property does not exist on the referenced type but the original
899 :       // type is an object type, see if any subtype has the property.
900 :       if (foundType == null) {
901 :         ObjectType maybeType = ObjectType.cast(
902 :             registry.getGreatestSubtypeWithProperty(type, field));
903 :         // getGreatestSubtypeWithProperty does not guarantee that the property
904 :         // is defined on the returned type, it just indicates that it might be,
905 :         // so we have to double check.
906 :         if (maybeType != null && maybeType.hasOwnProperty(field)) {
907 :           foundType = maybeType;
908 :         }
909 :       }
910 :       return foundType;
911 :     }"

"777 :     @Override public JSType getType(
778 :         StaticScope<JSType> scope, Node node, String prop) {
779 :       if (node.getJSType() == null) {
780 :         return registry.getNativeType(JSTypeNative.UNKNOWN_TYPE);
781 :       }
782 :       return node.getJSType();
783 :     }"

"834 :     @Override public Iterable<JSType> getTypeAlternatives(JSType type) {
835 :       if (type.isUnionType()) {
836 :         return type.toMaybeUnionType().getAlternates();
837 :       } else {
838 :         ObjectType objType = type.toObjectType();
839 :         if (objType != null &&
840 :             objType.getConstructor() != null &&
841 :             objType.getConstructor().isInterface()) {
842 :           List<JSType> list = Lists.newArrayList();
843 :           for (FunctionType impl
844 :                    : registry.getDirectImplementors(objType)) {
845 :             list.add(impl.getInstanceType());
846 :           }
847 :           return list;
848 :         } else {
849 :           return null;
850 :         }
851 :       }
852 :     }"

